def int_to_string(n):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    digits = []
    while n:
        digits.append(chr(ord('0') + n % 10))
        n //= 10
    return sign + "".join(digits[::-1])
```

