def create_chessboard(size=8):
  """Creates a chessboard pattern."""
  board = [[' ' for _ in range(size)] for _ in range(size)]
  for i in range(size):
    for j in range(size):
      if (i + j) % 2 == 0:
        board[i][j] = '#'
  return board
